motion:
/* hook + road: the road never sits still */
tl.fromTo("#hook", { scale: 1.0, transformOrigin: "50% 60%" }, { scale: 1.06, duration: 7.2, ease: "none" }, 3.9);
tl.fromTo("#roadart", { scale: 1.0 }, { scale: 1.06, duration: 4.8, ease: "none" }, 11.7);
/* the plant: two facts on their words */
tl.fromTo("#plant1", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 18.9);
tl.fromTo("#plant2", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 20.0);
/* rule 1 obeyed: the long way draws itself, twice around */
tl.fromTo("#loop", { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 2.6, ease: "power1.inOut" }, 27.5);
/* the mirror: the distance badge, and headlights that never change */
tl.fromTo("#dist", { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.3 }, 32.1);
/* rule 2 obeyed: you slow, they slow; you speed up, so do they */
tl.set("#speed2", { textContent: "38" }, 40.5);
tl.fromTo(["#hl1b", "#hl2b"], { scale: 1 }, { scale: 0.82, duration: 0.6, ease: "power1.inOut" }, 41.2);
tl.set("#speed2", { textContent: "62" }, 42.7);
tl.to(["#hl1b", "#hl2b"], { scale: 1.1, duration: 0.6, ease: "power1.inOut" }, 43.4);
/* radio */
tl.fromTo("#radiobox", { scale: 0.98 }, { scale: 1.04, duration: 6.2, ease: "none" }, 45.1);
tl.set("#radioline", { textContent: "" }, 45.1);
tl.to("#radioline", { duration: 1.3, scrambleText: { text: "DO NOT CONVOY", chars: "upperCase", speed: 0.6 } }, 49.0);
/* rule 3 obeyed: lights off — the road goes dark on the word */
tl.fromTo("#roadon", { opacity: 1 }, { opacity: 0, duration: 0.25, ease: "none" }, 57.3);
/* they flash: three quick pulses */
tl.fromTo(["#hl1c", "#hl2c"], { opacity: 0.2 }, { opacity: 1, duration: 0.18, yoyo: true, repeat: 5, ease: "none" }, 64.6);
/* the pattern, drawn on as it is spoken */
[66.75, 67.05, 67.35].forEach((t, i) => tl.fromTo(`#dl${i}`, { opacity: 0, scaleX: 0.3 }, { opacity: 1, scaleX: 1, duration: 0.22, ease: "power2.out" }, t));
[67.95, 68.15, 68.35].forEach((t, i) => tl.fromTo(`#ds${i}`, { opacity: 0, scale: 0.3 }, { opacity: 1, scale: 1, duration: 0.16, ease: "power2.out" }, t));
[68.95, 69.25, 69.55].forEach((t, i) => tl.fromTo(`#dl${i + 3}`, { opacity: 0, scaleX: 0.3 }, { opacity: 1, scaleX: 1, duration: 0.22, ease: "power2.out" }, t));
/* the word resolves */
tl.to("#sosword", { duration: 1.0, scrambleText: { text: "S.O.S.", chars: "upperCase", speed: 0.7, revealDelay: 0.3 } }, 71.8);
/* you keep driving */
tl.fromTo("#roadart3", { scale: 1.0 }, { scale: 1.08, duration: 2.0, ease: "none" }, 74.1);
/* their lights do not fade. They go out. */
tl.to(["#hl1e", "#hl2e"], { opacity: 0, duration: 0.2, ease: "none" }, 79.7);
